insert into public.waste_categories
  (key, name, bin_label, bin_color, description, examples, ra9003_term, icon, sort_order)
values
  ('biodegradable', 'Biodegradable', 'Green Bin', '#2EA043', 'Organic waste that breaks down naturally and can be composted.', 'Food scraps, fruit peels, leaves, used tissue paper', 'Biodegradable / compostable', 'leaf', 1),
  ('recyclable', 'Recyclable', 'Blue Bin', '#0A84FF', 'Clean, dry materials that can be made into new products.', 'Plastic bottles, glass, metal, clean paper', 'Recyclable', 'recycle', 2),
  ('residual', 'Residual', 'Black Bin', '#111111', 'Waste that cannot be composted or recycled here and goes to disposal.', 'Mixed garbage, soiled packaging, and sanitary waste', 'Residual', 'trash', 3),
  ('hazardous', 'Hazardous waste', 'Red Bin', '#E5484D', 'Special waste that can harm people or the environment. Use the red bin or a collection point.', 'Chemicals, batteries, busted light bulbs, and expired medicines', 'Special waste', 'alert-triangle', 4)
on conflict (key) do update set
  name = excluded.name, bin_label = excluded.bin_label, bin_color = excluded.bin_color,
  description = excluded.description, examples = excluded.examples,
  ra9003_term = excluded.ra9003_term, icon = excluded.icon, sort_order = excluded.sort_order;

insert into public.waste_items
  (class_key, display_name, display_name_fil, category_key, short_instruction, reuse_tip,
   prep_steps, why_text, contamination_note, search_aliases, is_detectable, rule_source)
values
  ('plastic_bottle', 'Plastic bottle', 'Plastik na bote', 'recyclable', 'Empty it, remove the cap, and flatten it. Drop it in the blue bin.', 'Refill it for water or use it for plant cuttings.', '[{"title": "Empty it", "detail": "Pour out any drink left inside."}, {"title": "Remove the cap", "detail": "Caps are a different plastic. Put the cap in the blue bin separately."}, {"title": "Flatten it", "detail": "Squeeze out the air to save space, then use the blue bin."}]'::jsonb, 'PET bottles are widely recycled when they are empty and clean. Leftover liquid spoils other recyclables.', 'If it has leftover drink, empty and rinse it first.', array['bottle', 'water bottle', 'pet bottle', 'softdrinks bottle', 'bote', 'plastik na bote', 'mineral water']::text[], true, 'RA, FG'),
  ('plastic_cup', 'Plastic cup', 'Plastik na baso', 'recyclable', 'Empty and rinse it, then drop it in the blue bin.', 'Reuse it as a pen holder or seedling pot.', '[{"title": "Empty it", "detail": "Finish or pour out the drink and remove the straw."}, {"title": "Rinse it", "detail": "A quick rinse removes milk tea or juice residue."}, {"title": "Sort it", "detail": "Drop the clean cup in the blue bin. The straw goes in the black bin."}]'::jsonb, 'Clean PP and PET cups are accepted by junk shops. Sticky residue makes them unrecyclable.', 'If it has milk tea residue or food, rinse it or use the black bin.', array['cup', 'milk tea cup', 'plastic glass', 'baso', 'plastik na baso', 'milktea']::text[], true, 'RA, FG (R5)'),
  ('aluminum_can', 'Aluminum can', 'Lata', 'recyclable', 'Empty it and crush it, then drop it in the blue bin.', null, '[{"title": "Empty it", "detail": "Make sure no drink is left inside."}, {"title": "Crush it", "detail": "Step on it or squeeze it to save space."}, {"title": "Sort it", "detail": "Drop it in the blue bin."}]'::jsonb, 'Aluminum can be recycled again and again without losing quality.', 'Empty it fully before sorting.', array['can', 'soda can', 'softdrinks can', 'beer can', 'lata', 'tin can']::text[], true, 'RA, FG'),
  ('glass_bottle', 'Glass bottle', 'Boteng salamin', 'recyclable', 'Empty it and keep it whole. Place it in the blue bin.', 'Reuse it as a container or vase.', '[{"title": "Empty it", "detail": "Pour out any liquid left inside."}, {"title": "Keep it whole", "detail": "Place it gently so it does not break."}, {"title": "Sort it", "detail": "Put it in the blue bin."}]'::jsonb, 'Whole glass bottles can be reused or remelted. Broken glass is a danger to waste workers.', 'Broken glass: wrap it and give it to staff. Do not put it in any bin loose.', array['glass', 'bottle', 'jar', 'bote', 'boteng salamin', 'garapon']::text[], true, 'RA, FG'),
  ('paper_bag', 'Paper bag', 'Supot na papel', 'recyclable', 'Empty it and flatten it, then drop it in the blue bin.', 'Reuse it first. If it is still clean and sturdy, keep it for another trip. Recycle it when it is no longer usable.', '[{"title": "Check the bag", "detail": "Keep it only if it is clean, dry and intact."}, {"title": "Give it another use", "detail": "Use it for dry storage or your next shopping trip."}, {"title": "Recycle when worn out", "detail": "Empty and flatten it, then use the blue bin."}]'::jsonb, 'Reusing extends the life of paper fibers. Clean, dry paper can then be recycled; grease-soaked paper cannot.', 'Greasy or food-soaked paper goes in the black bin.', array['paper bag', 'brown bag', 'takeout bag', 'supot', 'supot na papel']::text[], true, 'RA, FG, FW'),
  ('cardboard', 'Cardboard', 'Karton', 'recyclable', 'Flatten it and keep it dry. Place it in the blue bin.', 'Reuse it for storage or packing.', '[{"title": "Empty it", "detail": "Remove any contents, plastic wrap or foam."}, {"title": "Flatten it", "detail": "Open the flaps and fold it flat."}, {"title": "Keep it dry", "detail": "Put it in the blue bin away from wet waste."}]'::jsonb, 'Dry cardboard is easy to recycle into new boxes. Wet or greasy cardboard is not.', 'Wet or greasy cardboard (e.g. pizza box bottom) goes in the black bin.', array['box', 'carton', 'karton', 'kahon', 'pizza box']::text[], true, 'RA, FG'),
  ('paper_sheet', 'Paper', 'Papel', 'recyclable', 'Keep it dry and uncrumpled. Place it in the blue bin.', 'Use the blank side for notes.', '[{"title": "Use both sides", "detail": "Scratch paper still has a blank side for notes."}, {"title": "Keep it dry and flat", "detail": "Do not crumple or wet it."}, {"title": "Sort it", "detail": "Place it in the blue bin."}]'::jsonb, 'Clean, flat paper has long fibers that recycle well.', 'Wet or food-stained paper goes in the black bin.', array['paper', 'bond paper', 'notebook paper', 'papel', 'scratch paper', 'printout']::text[], true, 'RA, FG'),
  ('banana_peel', 'Banana peel', 'Balat ng saging', 'biodegradable', 'Remove stickers, then compost or use the green bin.', null, '[{"title": "Remove stickers", "detail": "Fruit stickers are plastic and go in the black bin."}, {"title": "Compost or green bin", "detail": "Add it to a compost pile or the green bin."}]'::jsonb, 'Organic material breaks down naturally.', null, array['banana', 'peel', 'fruit peel', 'saging', 'balat ng saging']::text[], true, 'RA, FG, FW'),
  ('food_scraps', 'Food scraps', 'Tira-tirang pagkain', 'biodegradable', 'Scrape food into the green bin. No plastic or packaging.', null, '[{"title": "Separate the packaging", "detail": "Take food out of wrappers and containers."}, {"title": "Scrape it in", "detail": "Put only the food in the green bin."}]'::jsonb, 'Food waste can be composted. Mixed with plastic, it can''t.', 'Remove any wrapper or container first.', array['leftovers', 'food waste', 'rice', 'fruit peel', 'tira', 'tirang pagkain', 'kanin', 'mango peel']::text[], true, 'RA, FG'),
  ('leaves', 'Leaves', 'Dahon', 'biodegradable', 'Place in the green bin or compost.', null, '[{"title": "Remove litter", "detail": "Pick out any plastic or wrappers mixed in."}, {"title": "Compost or green bin", "detail": "Leaves make good compost."}]'::jsonb, 'Garden waste breaks down into useful compost.', null, array['leaf', 'dry leaves', 'dahon', 'twigs', 'grass', 'garden waste']::text[], true, 'RA, FG'),
  ('used_tissue', 'Used tissue', 'Gamit na tisyu', 'biodegradable', 'Place in the green bin.', null, '[{"title": "Check what it touched", "detail": "Plain tissue can be composted."}, {"title": "Sort it", "detail": "Use the green bin, or the black bin if it touched chemicals or blood."}]'::jsonb, 'Plain tissue is paper fiber and breaks down naturally.', 'Tissue used with chemicals or for blood goes in the black bin.', array['tissue', 'table napkin', 'paper towel', 'tisyu']::text[], true, 'FG (R2)'),
  ('snack_wrapper', 'Snack wrapper', 'Balot ng chichirya', 'residual', 'Empty any food, then place it in the black bin.', null, '[{"title": "Empty it", "detail": "Shake out crumbs into the green bin."}, {"title": "Sort it", "detail": "Place the wrapper in the black bin."}]'::jsonb, 'Mixed-layer film is not recyclable here.', null, array['chips bag', 'candy wrapper', 'junk food', 'chichirya', 'balot', 'sitsirya', 'biscuit wrapper']::text[], true, 'RA, FG, FW'),
  ('styrofoam', 'Styrofoam', 'Styro', 'residual', 'Empty any food, then place it in the black bin.', null, '[{"title": "Empty it", "detail": "Scrape leftover food into the green bin."}, {"title": "Sort it", "detail": "Place the styrofoam in the black bin."}]'::jsonb, 'Styrofoam is not recycled locally and breaks into small pieces that pollute.', null, array['styro', 'foam', 'styrofoam box', 'styrofoam cup', 'polystyrene']::text[], true, 'RA, FG'),
  ('plastic_utensil', 'Plastic utensil', 'Plastik na kubyertos', 'residual', 'Place it in the black bin.', 'Wash and reuse it if it is still intact.', '[{"title": "Reuse if you can", "detail": "Wash it and keep it for another meal."}, {"title": "Sort it", "detail": "When worn out, place it in the black bin."}]'::jsonb, 'Small single-use plastics are too small and mixed to recycle here.', null, array['spoon', 'fork', 'plastic spoon', 'plastic fork', 'kutsara', 'tinidor', 'kubyertos']::text[], true, 'RA, FG'),
  ('straw', 'Straw', 'Straw', 'residual', 'Place it in the black bin.', 'Next time, skip the straw or bring a reusable one.', '[{"title": "Sort it", "detail": "Place the straw in the black bin."}, {"title": "Skip it next time", "detail": "Bring a reusable straw or drink without one."}]'::jsonb, 'Straws are too small and light to be recycled.', null, array['straw', 'plastic straw', 'drinking straw', 'istro']::text[], true, 'RA, FG'),
  ('tetra_pack', 'Tetra Pak / juice carton', 'Karton ng juice', 'residual', 'Empty and flatten it, then place it in the black bin.', null, '[{"title": "Empty it", "detail": "Finish or pour out the drink."}, {"title": "Flatten it", "detail": "Press it flat to save space."}, {"title": "Sort it", "detail": "Place it in the black bin, or a carton drop-off if your area has one."}]'::jsonb, 'Cartons mix paper, plastic and aluminum layers that most junk shops don''t accept.', 'Some drop-off programs accept clean cartons. Check locally.', array['tetra pak', 'juice box', 'milk carton', 'zesto', 'karton ng juice', 'drink box']::text[], true, 'RA (R3)'),
  ('soiled_food_container', 'Soiled food container', 'Maruming lalagyan ng pagkain', 'residual', 'Scrape leftover food into the green bin, then put the container in the black bin.', null, '[{"title": "Scrape the food", "detail": "Put leftover food in the green bin."}, {"title": "Sort the container", "detail": "Place the dirty container in the black bin."}]'::jsonb, 'Food-soiled packaging can''t be recycled, but the food itself can be composted.', null, array['takeout box', 'food container', 'lunch box', 'lalagyan', 'baonan', 'packed lunch']::text[], true, 'RA, FG'),
  ('sanitary_napkin', 'Sanitary napkin', 'Napkin', 'residual', 'Wrap it in paper, then place it in the black bin.', null, '[{"title": "Wrap it", "detail": "Wrap it in paper or its wrapper."}, {"title": "Sort it", "detail": "Place it in the black bin."}]'::jsonb, 'Sanitary waste is a health risk and must not be recycled or composted.', null, array['pad', 'sanitary pad', 'napkin', 'feminine napkin', 'panty liner']::text[], true, 'RA, FG'),
  ('face_mask', 'Face mask', 'Face mask', 'residual', 'Fold it inward, cut the ear loops, and place it in the black bin.', null, '[{"title": "Fold it inward", "detail": "Keep the used side inside."}, {"title": "Cut the ear loops", "detail": "Loops can trap animals."}, {"title": "Sort it", "detail": "Place it in the black bin."}]'::jsonb, 'Used masks may carry germs and are made of mixed materials that can''t be recycled.', null, array['mask', 'surgical mask', 'facemask', 'kn95']::text[], true, 'RA (R4)'),
  ('battery', 'Battery', 'Baterya', 'hazardous', 'Tape the terminals. Take it to a battery collection point.', null, '[{"title": "Tape the terminals", "detail": "Cover both ends with tape to prevent sparks."}, {"title": "Bring it to a collection point", "detail": "Use the red bin or a battery drop-off."}]'::jsonb, 'Batteries can leak or start fires. Never mix with regular waste.', 'Never mix with regular waste. Batteries can leak or start fires.', array['batteries', 'aa battery', 'aaa battery', 'baterya', 'lithium battery', 'battery cell']::text[], true, 'RA, FG, FW'),
  ('light_bulb', 'Light bulb', 'Bombilya', 'hazardous', 'Keep it whole and wrap it. Give it to staff or a collection point.', null, '[{"title": "Keep it whole", "detail": "Do not break it."}, {"title": "Wrap it", "detail": "Use paper or its original box."}, {"title": "Hand it over", "detail": "Give it to staff or a hazardous waste collection point."}]'::jsonb, 'Fluorescent bulbs contain mercury, which is toxic when released.', 'Fluorescent bulbs contain mercury. Do not break them.', array['bulb', 'lamp', 'fluorescent', 'led bulb', 'bombilya', 'ilaw']::text[], true, 'RA, FG'),
  ('expired_medicine', 'Medicine / blister pack', 'Gamot', 'hazardous', 'Keep it in its pack. Bring it to a pharmacy or hazardous waste collection point.', null, '[{"title": "Keep it packed", "detail": "Leave pills in their blister or bottle."}, {"title": "Bring it to a drop-off", "detail": "Use a pharmacy take-back or a hazardous waste collection point."}]'::jsonb, 'Medicines can poison water and soil if thrown away or flushed.', 'Do not flush or throw it in regular bins.', array['medicine', 'pills', 'tablets', 'blister pack', 'gamot', 'expired medicine', 'syrup']::text[], true, 'RA, FG'),
  ('spray_can', 'Spray / aerosol can', 'Spray can', 'hazardous', 'Do not puncture or burn it. Place it in the red bin or a collection point.', null, '[{"title": "Do not puncture it", "detail": "Pressurized cans can explode."}, {"title": "Sort it", "detail": "Place it in the red bin or a collection point."}]'::jsonb, 'Aerosol cans hold pressure and chemicals that are dangerous in regular waste.', 'Can explode under heat or pressure.', array['aerosol', 'spray', 'insect spray', 'deodorant spray', 'spray paint', 'baygon']::text[], true, 'RA, FG'),
  ('paper_cup', 'Paper cup', 'Papel na baso', 'residual', 'Empty it, then place it in the black bin.', 'Bring a reusable tumbler next time.', '[]'::jsonb, 'Paper cups have a plastic lining, so they can''t be recycled with paper.', null, array['coffee cup', 'paper cup', 'hot cup']::text[], false, 'RA (spec §3.3)'),
  ('cigarette_butt', 'Cigarette butt', 'Upos', 'residual', 'Make sure it is fully out, then place it in the black bin.', null, '[]'::jsonb, 'Filters are plastic and contain toxins.', null, array['cigarette', 'upos', 'yosi', 'filter']::text[], false, 'RA (spec §3.3)'),
  ('bamboo_skewer', 'Chopsticks / bamboo skewer', 'Barbecue stick', 'biodegradable', 'Break sharp tips, then place it in the green bin.', null, '[]'::jsonb, 'Untreated bamboo and wood break down naturally.', 'Plastic chopsticks go in the black bin.', array['chopsticks', 'skewer', 'barbecue stick', 'bbq stick', 'toothpick']::text[], false, 'RA (spec §3.3)'),
  ('eggshell', 'Eggshell', 'Balat ng itlog', 'biodegradable', 'Place it in the green bin or compost.', 'Crushed eggshells are good for garden soil.', '[]'::jsonb, 'Eggshells are organic and add calcium to compost.', null, array['egg', 'egg shell', 'itlog', 'balat ng itlog']::text[], false, 'RA (spec §3.3)'),
  ('coffee_grounds', 'Coffee grounds', 'Sapal ng kape', 'biodegradable', 'Place them in the green bin or compost.', 'Use them as garden fertilizer.', '[]'::jsonb, 'Coffee grounds are organic and compost well.', 'Coffee pods and sachets go in the black bin.', array['coffee', 'grounds', 'kape', 'tea leaves']::text[], false, 'RA (spec §3.3)'),
  ('plastic_sachet', 'Plastic sachet', 'Sachet', 'residual', 'Empty it, then place it in the black bin.', 'Choose refill stations or bigger packs when you can.', '[]'::jsonb, 'Sachets are multi-layer plastic and are not recycled here.', null, array['sachet', 'shampoo sachet', 'coffee sachet', '3in1', 'ketchup packet']::text[], false, 'RA (spec §3.3)'),
  ('rubber_band', 'Rubber band', 'Goma', 'residual', 'Reuse it, or place it in the black bin.', 'Keep it for bundling things.', '[]'::jsonb, 'Small rubber items are not recycled here.', null, array['rubber', 'goma', 'rubber band', 'lastiko']::text[], false, 'RA (spec §3.3)'),
  ('e_waste', 'E-waste (phones, cables, chargers)', 'E-waste', 'hazardous', 'Do not throw it in any bin. Bring it to an e-waste collection point.', 'Donate or repair working devices.', '[]'::jsonb, 'Electronics contain metals and chemicals that are harmful but valuable to recover.', null, array['phone', 'cellphone', 'charger', 'cable', 'earphones', 'electronics', 'gadget']::text[], false, 'RA (spec §3.3)'),
  ('paint_can', 'Paint can', 'Lata ng pintura', 'hazardous', 'Keep it closed. Bring it to a hazardous waste collection point.', null, '[]'::jsonb, 'Leftover paint and solvents are toxic.', null, array['paint', 'pintura', 'thinner', 'solvent']::text[], false, 'RA (spec §3.3)'),
  ('broken_glass', 'Broken glass', 'Basag na salamin', 'residual', 'Wrap it well and label it "sharp". Give it to staff.', null, '[]'::jsonb, 'Loose broken glass injures waste workers.', 'Never put loose broken glass in any bin.', array['glass shards', 'bubog', 'basag', 'broken bottle']::text[], false, 'RA (spec §3.3)'),
  ('diaper', 'Diaper', 'Lampin', 'residual', 'Roll it up and tape it, then place it in the black bin.', null, '[]'::jsonb, 'Diapers are sanitary waste and can''t be recycled or composted.', null, array['diaper', 'nappy', 'lampin', 'adult diaper']::text[], false, 'RA (spec §3.3)'),
  ('pen', 'Pen', 'Ballpen', 'residual', 'Place it in the black bin.', 'Use refillable pens.', '[]'::jsonb, 'Pens mix plastic, metal and ink, so they aren''t recycled here.', null, array['ballpen', 'ball pen', 'marker', 'highlighter']::text[], false, 'RA (spec §3.3)'),
  ('ink_cartridge', 'Ink cartridge', 'Ink cartridge', 'hazardous', 'Bring it to a cartridge take-back or e-waste collection point.', 'Many printer shops refill cartridges.', '[]'::jsonb, 'Ink and electronics in cartridges are harmful in regular waste.', null, array['printer ink', 'toner', 'cartridge', 'ink']::text[], false, 'RA (spec §3.3)')
